window.BANQUE_INFINI = {"module":"annee-1/pratique/semestre-2/mobilisation-accessoire","titre":"Mobilisation accessoire","sources":[{"t":"Colonne","q":"colonne/quiz.html","f":"colonne/fiche.html"},{"t":"Membre inférieur","q":"membre-inferieur/quiz.html","f":"membre-inferieur/fiche.html"},{"t":"Membre supérieur","q":"membre-superieur/quiz.html","f":"membre-superieur/fiche.html"},{"t":"Posture — bilan postural","q":"posture/quiz.html","f":"posture/fiche.html"}],"questions":[{"q":"Quelle est la fonction des lordoses ?","o":["Le MOUVEMENT","La PROTECTION","La stabilité pure","L'amortissement uniquement"],"r":0,"e":"Lordose cervicale et lombaire = mouvement ; cyphose dorsale et sacrée = protection.","s":0},{"q":"Quelle est la fonction des cyphoses ?","o":["La PROTECTION","Le MOUVEMENT","La propulsion","L'extension"],"r":0,"e":"Les cyphoses dorsale et sacrée protègent les organes.","s":0},{"q":"Pourquoi les lordoses subissent-elles plus d'usure discale ?","o":["Ce sont des zones de support","Elles sont plus mobiles uniquement","Elles sont moins vascularisées","Leurs disques sont plus fins"],"r":0,"e":"D'où l'objectif de diminuer la compression à ces niveaux.","s":0},{"q":"Quelle est l'amplitude de flexion cervicale selon Kapandji (2019) ?","o":["40°","75°","60°","35°"],"r":0,"e":"Extension cervicale 75° : l'extension est plus ample que la flexion.","s":0},{"q":"Quelle est l'amplitude d'extension cervicale selon Kapandji ?","o":["75°","40°","60°","35°"],"r":0,"e":"C'est l'inverse de la goniométrie clinique du module de goniométrie.","s":0},{"q":"Quelle est l'amplitude de flexion lombaire selon Kapandji ?","o":["60°","35°","40°","105°"],"r":0,"e":"Extension lombaire 35°.","s":0},{"q":"Quelle est l'amplitude de flexion de l'ensemble dorso-lombaire ?","o":["105°, dont 45° dorsal","60°, dont 25° dorsal","95°, dont 40° dorsal","140°"],"r":0,"e":"Extension dorso-lombaire 60°, dont 25° dorsal.","s":0},{"q":"À quel niveau l'artère vertébrale entre-t-elle ?","o":["C6","C1","C7","T1"],"r":0,"e":"Elle passe ensuite en arrière des apophyses transverses, dans le foramen transversaire.","s":0},{"q":"Par où passe l'artère vertébrale ?","o":["Dans le foramen transversaire des cervicales","En avant des corps vertébraux cervicaux","Dans le canal rachidien, en avant de la moelle","Le long des épineuses, en arrière des lames"],"r":0,"e":"Ce trajet explique la sensibilité aux mouvements cervicaux. Elle chemine en arrière des apophyses transverses.","s":0},{"q":"Quels mouvements augmentent la compression de l'artère vertébrale ?","o":["L'extension et la rotation","La flexion et l'inclinaison","La traction axiale","Aucun"],"r":0,"e":"L'extension augmente l'étirement, la rotation la tension du côté opposé.","s":0},{"q":"Combien de temps dure chaque position du test de l'artère vertébrale ?","o":["10 à 15 secondes","3 à 5 secondes","30 secondes","1 minute"],"r":0,"e":"Cinq étapes : hyperext., pause, hyperext.+rot. droite, pause, hyperext.+rot. gauche.","s":0},{"q":"Quelle est la position de départ du test de l'artère vertébrale ?","o":["Assis, pieds appuyés, kiné en face","Couché sur le dos, kiné à la tête","Debout, dos au mur, kiné sur le côté","En décubitus latéral, kiné derrière"],"r":0,"e":"Le kiné se place en face du patient.","s":0},{"q":"Que faire en cas de vertiges ou nausées pendant le test ?","o":["Arrêter, la mobilisation étant contre-indiquée","Poursuivre le test, mais plus lentement","Réduire l'amplitude, puis reprendre le test","Changer de côté, puis terminer le test"],"r":0,"e":"Ce sont les signes d'insuffisance vertébro-basilaire. La mobilisation accessoire est alors contre-indiquée.","s":0},{"q":"Que provoque une compression des artères vertébrales ?","o":["Une insuffisance vasculaire cérébrale","Une compression radiculaire au membre supérieur","Une hernie discale cervicale","Une contracture réflexe des scalènes"],"r":0,"e":"C'est le syndrome de l'artère vertébro-basilaire.","s":0},{"q":"Qu'évaluent les mouvements PASSIFS ?","o":["Les éléments non contractiles, amplitude et end-feel","Les éléments contractiles, force et contrôle","La force musculaire, mesurée en contraction isométrique","L'endurance, sur des répétitions lentes"],"r":0,"e":"Les mouvements actifs évaluent les éléments contractiles. On explore aussi la douleur et le schéma capsulaire.","s":0},{"q":"Qu'évaluent les mouvements ACTIFS ?","o":["Les éléments contractiles, qualité et quantité du geste","Les éléments non contractiles, end-feel compris","Le schéma capsulaire, propre à chaque articulation testée","L'end-feel, ressenti en fin d'amplitude"],"r":0,"e":"On observe compensation, harmonie et rythme. On observe aussi le rythme du mouvement.","s":0},{"q":"Quels symptômes attendre en cas de problème cervical ?","o":["Moins d'amplitude, douleur, paresthésies, signes vasculaires","Fièvre, frissons, sueurs nocturnes et amaigrissement rapide","Œdème des membres, rougeur et chaleur locales","Troubles digestifs, nausées et perte d'appétit"],"r":0,"e":"Quatre symptômes attendus.","s":0},{"q":"Quelles sont les divisions du rachis cervical ?","o":["C1-C3 supérieur, C4-C5 moyen, C6-C7 inférieur","C1-C2 supérieur, C3-C5 moyen, C6-C7 inférieur","C1-C4 supérieur, C5-C6 moyen, C7 inférieur","C1-C3 supérieur, C4-C7 inférieur, sans moyen"],"r":0,"e":"Trois divisions à connaître.","s":0},{"q":"Quelles sont les divisions du rachis dorsal ?","o":["D1-D4 supérieur, D5-D12 moyen et inférieur","D1-D6 supérieur, D7-D10 moyen, D11-D12 inférieur","D1-D5 supérieur, D6-D12 moyen et inférieur","D1-D3 supérieur, D4-D12 moyen et inférieur"],"r":0,"e":"Cette division conditionne la position du kiné.","s":0},{"q":"Quel rythme utiliser pour traiter la douleur ?","o":["Rythme lent, grades 1 et 2","Rythme staccato, grades 3 et 4","Rythme rapide, grade 5","Peu importe"],"r":0,"e":"Le rythme staccato des grades 3-4 sert à rompre les adhérences.","s":0},{"q":"Quel rythme utiliser pour rompre les adhérences ?","o":["Rythme staccato, grades 3 et 4","Rythme lent, grades 1 et 2","Rythme rapide, grade 5","Rythme continu"],"r":0,"e":"Le staccato est réservé aux grades élevés.","s":0},{"q":"Où se place le kiné pour les mouvements accessoires de D1 à D5 ?","o":["En tête de table, au chevet du patient","Latéralement, du côté à mobiliser","Au pied de la table, face aux pieds du patient","Debout, du côté opposé à la lésion"],"r":0,"e":"Pour D6-D12, il se place latéralement, du côté à mobiliser.","s":0},{"q":"Où se place le kiné pour les mouvements accessoires de D6 à D12 ?","o":["Latéralement, du côté à mobiliser","En tête de table, au chevet","Au pied de la table, en bout","Derrière le patient, assis sur un tabouret"],"r":0,"e":"Le positionnement change à partir de D6.","s":0},{"q":"Quand utiliser les PAU plutôt que les PAC ?","o":["Quand les symptômes sont unilatéraux ou asymétriques","Dans tous les cas, quels que soient les symptômes","Jamais, les PAC étant toujours plus efficaces au rachis","Uniquement au rachis lombaire, et non au cervical"],"r":0,"e":"Les postéro-antérieurs unilatéraux ciblent les apophyses articulaires.","s":0},{"q":"Quel effet a la flexion sur les trous de conjugaison ?","o":["Elle les augmente","Elle les diminue","Elle ne les modifie pas","Elle les ferme complètement"],"r":0,"e":"L'extension, elle, les diminue.","s":0},{"q":"Pourquoi le mouvement accessoire doit-il être généré par le corps du kiné ?","o":["Pour un mouvement rythmique et contrôlé, sans les bras","Pour économiser sa force sur une longue séance","Pour aller plus vite, et enchaîner davantage de techniques","Pour améliorer la lecture de l'end-feel"],"r":0,"e":"Le cours insiste : par le mouvement du corps, non avec les bras.","s":0},{"q":"Quel mouvement cervical est considéré comme un test des symptômes ?","o":["Le longitudinal céphalique","Le postéro-antérieur central","Le longitudinal caudal","Le transverse latéral"],"r":0,"e":"Il permet aussi de gagner la confiance du patient.","s":0},{"q":"Que faire en condition aiguë, comme un torticolis ?","o":["Respecter la position antalgique du patient","Forcer l'amplitude dans le sens douloureux","Utiliser d'emblée le grade 5, la manipulation","Reporter tout traitement à plus tard"],"r":0,"e":"Le mouvement se réalise en respectant la position antalgique.","s":0},{"q":"Quelle position du coude pour le PA sacro-iliaque sur le sacrum ?","o":["Coude en extension","Coude en flexion","Coude à 90°","Peu importe"],"r":0,"e":"Pour le longitudinal caudal et céphalique, le coude est en flexion.","s":0},{"q":"Quelle face des EIAS correspond à la compression sacro-iliaque ?","o":["La face interne","La face externe","Les deux","Aucune"],"r":0,"e":"Face interne = compression, face externe = décompression.","s":0},{"q":"Selon Kapandji (2019), l'amplitude d'extension lombaire est de :","o":["25°","35°","60°","75°"],"r":1,"e":"La flexion lombaire atteint 60°, la flexion cervicale 40° et l'extension cervicale 75°.","s":0},{"q":"Dans l'ensemble dorso-lombaire, la part dorsale de la flexion est de :","o":["25° sur 105°","45° sur 105°","60° sur 105°","105° en totalité"],"r":1,"e":"En extension, la part dorsale est de 25° sur 60°.","s":0},{"q":"Parmi les muscles pré-vertébraux, le cours cite :","o":["Longs de la tête et du cou, scalènes, sterno-cléido-mastoïdiens","Sous-occipitaux, interépineux et intertransversaires","Multifides, rotateurs et semi-épineux du cou et de la tête","Spléniers, trapèze supérieur, élévateur de la scapula et rhomboïdes"],"r":0,"e":"Sous-occipitaux, interépineux et intertransversaires forment le plan post-vertébral profond. Les droits antérieur et latéral de la tête en font aussi partie.","s":0},{"q":"Les semi-épineux et les multifides appartiennent au plan :","o":["Pré-vertébral","Post-vertébral profond","Post-vertébral intermédiaire","Post-vertébral superficiel"],"r":2,"e":"Ilio-costal cervical, long dorsal, spléniers, élévateur de la scapula et trapèze forment le plan superficiel.","s":0},{"q":"Le ligament jaune se situe :","o":["Entre les lames","Entre les épineuses","En avant des corps vertébraux","Dans le canal transversaire"],"r":0,"e":"Le ligament nucal se prolonge, lui, par le ligament supra-épineux.","s":0},{"q":"La position de départ du test de l'artère vertébrale est :","o":["Assis, pieds appuyés, kiné en face","Couché sur le dos, kiné à la tête","Debout, dos au mur, kiné sur le côté","En décubitus latéral, kiné derrière"],"r":0,"e":"Chaque position est tenue 10 à 15 secondes, avec des pauses de même durée.","s":0},{"q":"Les étapes du test de l'artère vertébrale sont :","o":["Hyperextension, puis avec rotation droite, puis gauche","Rotation seule à droite, puis à gauche, sans extension","Flexion, puis extension, puis inclinaison des deux côtés","Inclinaison à droite, puis à gauche, sans rotation"],"r":0,"e":"Chaque étape dure 10 à 15 secondes. Une pause sépare chaque étape.","s":0},{"q":"Parmi les signes d'alerte du test de l'artère vertébrale, outre les 5 D et 3 N, le cours cite :","o":["Ataxie, hémianesthésie, hémiplégie, troubles sensitifs","Douleur cervicale simple, sans autre signe","Raideur matinale du cou, cédant en une heure","Céphalée de tension, en casque, en fin de journée"],"r":0,"e":"Leur apparition impose l'interruption du test et contre-indique la mobilisation accessoire.","s":0},{"q":"Le syndrome vertébro-basilaire correspond à :","o":["Une compression des artères vertébrales, d'où une ischémie","Une compression médullaire cervicale, d'où une myélopathie","Une hernie discale cervicale, d'où une radiculalgie","Une contracture musculaire, d'où un torticolis"],"r":0,"e":"L'extension augmente l'étirement et la rotation la tension du côté opposé. Il s'agit d'une insuffisance vasculaire cérébrale.","s":0},{"q":"Dans les deux cas, actifs comme passifs, on évalue :","o":["Qualité, amplitude, douleur, résistance, spasme, contrôle","La seule amplitude, mesurée au goniomètre","La seule douleur, cotée sur une échelle visuelle","Le seul end-feel, ressenti en fin de mouvement passif forcé"],"r":0,"e":"Les mouvements passifs explorent en plus l'end-feel et le schéma capsulaire. On évalue le comportement de la douleur et le contrôle musculaire.","s":0},{"q":"Les symptômes attendus en cas de problème cervical sont :","o":["Raideur, douleur, paresthésies et signes vasculaires","Une faiblesse isolée, sans douleur ni trouble sensitif","Des vertiges isolés, sans douleur ni raideur","Une amyotrophie, sans douleur ni raideur"],"r":0,"e":"Les paresthésies et les signes vasculaires orientent vers une atteinte neuro-vasculaire associée. La raideur correspond à une diminution d'amplitude.","s":0},{"q":"Les divisions du rachis dorsal sont :","o":["D1-D4 supérieur, D5-D12 moyen et inférieur","D1-D6 supérieur, D7-D12 moyen et inférieur","D1-D3 supérieur, D4-D8 moyen, D9-D12 inférieur","D1-D12, sans aucune division"],"r":0,"e":"Le rachis cervical se divise en C1-C3 supérieur, C4-C5 moyen et C6-C7 inférieur.","s":0},{"q":"En vue antérieure, l'évaluation posturale cervicale porte sur :","o":["Le regard, l'inclinaison et la rotation de la tête","La position des omoplates, vue de face","Les courbures physiologiques, vues de profil","Les crêtes iliaques, la ligne blanche et les clavicules"],"r":0,"e":"De profil, on observe l'antériorisation, l'hyperextension et l'augmentation ou la rectification de la lordose. On observe l'horizontalité du regard et les asymétries.","s":0},{"q":"En vue antérieure, l'évaluation posturale dorsale porte sur :","o":["Les clavicules, la ligne blanche, l'inclinaison du tronc","La position des omoplates, au repos et au mouvement","Les bascules du bassin et la hauteur des crêtes iliaques","L'horizontalité du regard et la rotation de la tête"],"r":0,"e":"La position des omoplates s'apprécie, elle, en vue postérieure.","s":0},{"q":"Pour la rotation cervicale active avec end-feel, la prise est :","o":["Une main sur l'épaule et l'autre sur le menton, kiné derrière","Deux mains sur l'occiput, kiné devant le patient","Une main sur le front et l'autre sur la nuque, kiné à côté","Une main sur le sternum et l'autre sur la tempe, kiné devant"],"r":0,"e":"Pour l'inclinaison, la seconde main se place au-dessus de l'oreille controlatérale. L'épaule et le menton sont du côté controlatéral.","s":0},{"q":"Pour la rotation cervicale passive, le mouvement se fait :","o":["Vers la main du menton, l'avant-bras soutenant la tête","Vers la main occipitale, la tête restant sur la table","Sans soutien, la tête tournant librement sur la table","Par la seule main occipitale, l'autre restant libre"],"r":0,"e":"Le patient est en décubitus dorsal, le kiné derrière et assis. L'avant-bras soutient la tête en fin d'amplitude.","s":0},{"q":"Pour les mouvements passifs de D1-D4, le cours précise que l'inclinaison et la rotation se font :","o":["Vers le dessus seulement, d'où un changement de côté","Dans les deux sens, sans changer de position","En décubitus dorsal, la tête en bout de table","En position assise, les bras croisés sur la poitrine"],"r":0,"e":"Le patient est en décubitus latéral genoux fléchis, le kiné devant, et c'est le cervical qui provoque les mouvements de D1-D4. Il faut changer de décubitus latéral pour traiter l'autre côté.","s":0},{"q":"Lors des mouvements passifs de D1-D4 en rotation et inclinaison, la main sensitive palpe :","o":["Les apophyses transverses","Les apophyses épineuses","Les arcs postérieurs des côtes","Les lames vertébrales"],"r":0,"e":"En flexion-extension, elle palpe au contraire les épineuses et les espaces interépineux.","s":0},{"q":"L'amplitude de flexion cervicale selon Kapandji est de :","o":["25°","40°","60°","75°"],"r":1,"e":"L'extension cervicale atteint 75°, soit près du double.","s":0},{"q":"La lordose est associée dans le cours à la fonction de :","o":["Mouvement","Protection","Amortissement","Stabilisation"],"r":0,"e":"La cyphose, dorsale et sacrée, assure la protection ; la lordose, zone de support, subit davantage d'usure discale.","s":0},{"q":"Quelle technique de hanche facilite la rotation externe ?","o":["L'antéro-postérieur en décubitus latéral","Le postéro-antérieur en décubitus latéral","Le longitudinal caudal, en traction","La compression en décubitus dorsal"],"r":0,"e":"Le cours le signale explicitement : ce mouvement facilite la rotation externe de hanche.","s":1},{"q":"Quelle technique du genou vise à augmenter l'amplitude de flexion ?","o":["Le postéro-antérieur en décubitus ventral","L'antéro-postérieur en décubitus dorsal","Le transverse externe, genou fléchi à angle droit","Le longitudinal caudal, genou tendu"],"r":0,"e":"C'est l'indication explicite du PA en DV, genou fléchi.","s":1},{"q":"Quel type d'articulation est la tibio-péronière inférieure ?","o":["Une syndesmose fibreuse","Une synoviale plane","Une trochléarthrose","Une condylarthrose"],"r":0,"e":"Elle n'a ni capsule ni liquide, et présente peu de mouvement.","s":1},{"q":"Quel os mobilise-t-on à la tibio-péronière inférieure ?","o":["Le péroné, via la malléole externe","Le tibia, via la malléole interne du patient","Le talus, via sa trochlée","Le calcanéum, via le talon"],"r":0,"e":"On parle de mobilité de la malléole externe.","s":1},{"q":"Pourquoi change-t-on de mains entre rotation interne et externe de l'astragale ?","o":["Car l'astragale se mobilise toujours vers le kiné","Pour reposer les mains entre deux séries","Pour changer l'axe de la mobilisation","Pour mieux varier les grades d'une rotation à l'autre"],"r":0,"e":"C'est la règle clé de la mobilisation tibio-tarsienne.","s":1},{"q":"Quelle précaution lors du transverse externe de hanche près de l'aine ?","o":["Bord cubital près de l'aine, cuisse calée contre son tronc","Toute la paume à plat, sur la face interne de la cuisse","Une compression forte, pour bien fixer la hanche","Aucun contact avec la cuisse, pour éviter toute gêne du patient"],"r":0,"e":"Le cours écrit ATTENTION À L'AINE en majuscules. Le cours insiste sur la prudence au niveau de l'aine.","s":1},{"q":"Que se passe-t-il si le drap est trop large pour le transverse externe en DL ?","o":["On mobilise la diaphyse fémorale au lieu de la hanche","Le patient glisse sur la table et perd tout son alignement","La prise devient plus confortable pour le kiné","Le mouvement gagne en efficacité et en amplitude"],"r":0,"e":"Le drap doit être bien plié et placé tout près de l'aine.","s":1},{"q":"À quoi servent les 10 points de Kaltenborn au tarse ?","o":["Évaluer l'alignement, repérer les restrictions, guider","Mesurer les amplitudes du tarse, à l'aide d'un goniomètre","Tester la force des muscles intrinsèques du pied","Évaluer la douleur de chaque articulation du tarse"],"r":0,"e":"Trois objectifs explicites. On évalue l'alignement des rangées, et les restrictions guident les techniques.","s":1},{"q":"Comment stabiliser le pied pour l'antéro-postérieur du genou à 70° de flexion ?","o":["Le kiné s'assoit sur le pied pour le fixer","Une sangle fixe le pied à la table","Un assistant fait contre-appui sur le dos du pied","Le patient maintient lui-même son pied"],"r":0,"e":"La main externe stabilise au-dessus de la rotule.","s":1},{"q":"Quelle main est dite « sensitive » dans l'antéro-postérieur coxo-fémoral ?","o":["La main céphalique, sous la hanche en région postérieure","La main caudale, sous l'EIAS en région antérieure","Les deux mains, qui palpent tour à tour l'interligne","Aucune, le mouvement étant guidé par le regard"],"r":0,"e":"La main caudale exécute le mouvement en AP.","s":1},{"q":"Où se place la main caudale pour l'antéro-postérieur coxo-fémoral en DD ?","o":["En avant, sous l'EIAS et au-dessus du grand trochanter","Sur le grand trochanter, en dehors de l'EIAS du patient","Sur la face antérieure de la cuisse, au tiers distal","Sur le genou, en avant de la rotule"],"r":0,"e":"Elle appuie la base de la main, doigts orientés.","s":1},{"q":"Comment réaliser le longitudinal caudal de hanche ?","o":["Mains emboîtées sur les condyles, traction vers les pieds","Une main sur le bassin, l'autre au genou, traction vers le haut","Une traction par la cheville, genou tendu","Une compression du grand trochanter vers la table"],"r":0,"e":"Il faut éviter d'agir sur les tissus mous. Les mains sont sur la partie distale de la cuisse.","s":1},{"q":"Comment se place le kiné pour le transverse interne / compression de hanche en DD ?","o":["Une main sur chaque trochanter, coudes en abduction","Les deux mains sur le même trochanter, coudes au corps","Une main au bassin, l'autre au genou du même côté","À califourchon sur la table, mains sur le bassin"],"r":0,"e":"On pousse vers l'autre hanche, qui est stabilisée par la main. La main externe agit par thénar et hypothénar sur le grand trochanter.","s":1},{"q":"Que stabilise la main céphalique pour l'antéro-postérieur de hanche en DL ?","o":["L'iliaque, postérieurement","L'iliaque, antérieurement","Le grand trochanter","Le genou"],"r":0,"e":"Pour le postéro-antérieur, elle stabilise l'iliaque antérieurement.","s":1},{"q":"Où se place le kiné pour le postéro-antérieur de hanche en DL ?","o":["Derrière le patient","Face au patient","Au pied de la table","En tête de table"],"r":0,"e":"En antéro-postérieur, il est face au patient.","s":1},{"q":"Où se place la main sensitive pour l'antéro-postérieur du genou, genou tendu ?","o":["Sous le genou, dans la région poplitée","Sur la rotule, en avant du genou","Sur la tubérosité tibiale, en avant du tibia","Au niveau du talon, sous la cheville"],"r":0,"e":"La main caudale agit avec thénar et hypothénar sur la TTA.","s":1},{"q":"Comment s'appelle la technique AP/PA avec les pouces sur la TTA, genoux fléchis ?","o":["Les tiroirs","Le roulement","Le pivot","La décoaptation"],"r":0,"e":"Cette variante bilatérale reproduit le test des tiroirs.","s":1},{"q":"Quel type d'articulation est la tibio-péronière supérieure ?","o":["Une arthrodie","Une trochléarthrose","Une énarthrose","Une syndesmose"],"r":0,"e":"C'est la tibio-péronière inférieure qui est une syndesmose.","s":1},{"q":"Que signifie la prise « en bec de canard » à la tibio-péronière supérieure ?","o":["Pousser avec le pouce et le 2ᵉ doigt","Pousser avec les deux pouces superposés","Pousser avec le 5ᵉ doigt et le bord cubital","Pousser avec la paume entière"],"r":0,"e":"C'est une variante de l'antéro-postérieur / postéro-antérieur.","s":1},{"q":"Comment réaliser la compression de la tibio-péronière supérieure ?","o":["Base des mains sur la tête du péroné et sur le tibia","Les deux mains sur la tête du péroné, coudes au corps","Une main au genou, l'autre à la cheville du patient","Une compression par la cheville, genou tendu"],"r":0,"e":"On pousse le péroné contre le tibia. La main externe est sur le péroné, l'interne sur le tibia, coudes en abduction.","s":1},{"q":"Où se place le pied du patient quand la flexion de genou augmente, en PA de la tibio-péronière supérieure ?","o":["Sous l'aisselle du kiné","Sur l'épaule du kiné","Sur la table","Au sol"],"r":0,"e":"Cela permet de suivre l'amplitude croissante.","s":1},{"q":"Comment mobilise-t-on la patella en longitudinal caudal ?","o":["Pouce et index sur le bord supérieur, poussée vers le pied","En saisissant toute la rotule, poussée vers la tête","En comprimant la rotule contre le fémur, poussée vers le pied","Avec le bord cubital, sur la pointe de la rotule"],"r":0,"e":"Ces mouvements peuvent être réalisés avec compression ou traction. La main caudale se place sur les bords distaux.","s":1},{"q":"Quels mouvements patello-fémoraux sont possibles en plus du longitudinal ?","o":["Transverses, rotations, compression ou traction","La compression seule, sans autre direction","Les transverses seuls, interne et externe","Les rotations seules, à droite et à gauche"],"r":0,"e":"Quatre familles de mouvements pour la patella.","s":1},{"q":"Quelle précaution lors du postéro-antérieur tibio-tarsien ?","o":["Ne pas comprimer le tendon d'Achille","Ne pas toucher les deux malléoles","Éviter tout contact avec la plante","Ne pas fléchir le genou du patient"],"r":0,"e":"La main céphalique en « U » se place sur la région postérieure de l'astragale.","s":1},{"q":"Dans quelle position doit être le pied pour l'antéro-postérieur tibio-tarsien ?","o":["En flexion plantaire","En flexion dorsale","En position neutre","En inversion"],"r":0,"e":"Le cours le précise explicitement pour l'AP.","s":1},{"q":"Comment réaliser le longitudinal caudal tibio-tarsien ?","o":["Mains en « U » sur l'astragale, traction vers le plafond","Compression du calcanéum vers la table","Traction par les orteils, le genou tendu, vers le plafond","Poussée sur la malléole externe vers la table"],"r":0,"e":"Le kiné stabilise la cuisse avec sa jambe. L'astragale et le calcanéum sont tractés ensemble.","s":1},{"q":"Comment réaliser le longitudinal céphalique tibio-tarsien ?","o":["Main sur le calcanéum plantaire, compression vers la table","Traction de l'astragale vers le plafond, mains en U","Poussée sur l'astragale, vers les orteils et vers le plafond","Compression des deux malléoles l'une vers l'autre"],"r":0,"e":"C'est l'inverse du longitudinal caudal.","s":1},{"q":"Quel est le principe des mouvements inter-métatarsiens ?","o":["Stabiliser un métatarsien et mobiliser l'adjacent","Mobiliser les deux métatarsiens en même temps","Comprimer l'ensemble de l'avant-pied entre les mains","Tracter les orteils, un par un, vers soi"],"r":0,"e":"Le cours conclut par : STABILISER ET MOBILISER. L'adjacent est mobilisé en antéro-postérieur ou en postéro-antérieur.","s":1},{"q":"Quel effet a le longitudinal céphalique en DL de la tibio-péronière supérieure ?","o":["Un effet sur la tibio-péronière inférieure","Un effet sur l'articulation du genou","Un effet sur la sous-talienne","Aucun effet sur une articulation à distance"],"r":0,"e":"Les deux articulations tibio-péronières sont couplées.","s":1},{"q":"Combien de mouvements accessoires sont listés pour les MTP et IP du pied ?","o":["Quatre","Trois","Cinq","Six"],"r":0,"e":"AP/PA, transverse droite/gauche, longitudinal caudal/céphalique, rotation droite/gauche.","s":1},{"q":"Le grade 2 de Maitland correspond à :","o":["Une petite amplitude, au début de la mobilité","Une grande amplitude, jusqu'à la résistance","Une grande amplitude, nettement dans la résistance","Une petite amplitude, rapide"],"r":1,"e":"Le grade 3 travaille en grande amplitude dans la résistance et le grade 4 en petite amplitude à la limite de celle-ci. Il se décline en 2− et 2+.","s":1},{"q":"Le grade 5 de Maitland correspond à :","o":["Une petite amplitude rapide, soit une manipulation","Une grande amplitude lente, jusqu'à la résistance","Un maintien statique, en fin d'amplitude","Une traction continue, maintenue plusieurs minutes"],"r":0,"e":"Les grades 1 et 2 visent la douleur, les grades 3 et 4 le gain d'amplitude.","s":1},{"q":"La mobilisation accessoire évalue :","o":["La mobilité, la douleur et les asymétries","La force, cotée de 0 à 5 sur chaque groupe musculaire","L'amplitude active, mesurée au goniomètre","L'endurance, sur des séries répétées"],"r":0,"e":"Ses objectifs sont de diminuer la douleur et d'augmenter l'amplitude ; l'hypermobilité en est une contre-indication. On repère aussi les désalignements.","s":1},{"q":"La démarche de la mobilisation accessoire suit l'ordre :","o":["Évaluation, enregistrement, raisonnement, intervention","Intervention, évaluation, raisonnement, enregistrement","Raisonnement, évaluation, intervention, enregistrement","Enregistrement, évaluation, intervention, raisonnement"],"r":0,"e":"Elle ne s'applique qu'à l'hypomobilité. Le raisonnement est clinique.","s":1},{"q":"Le bourrelet cotyloïdien augmente la surface articulaire de la hanche d'environ :","o":["10 %","20 %","30 %","50 %"],"r":2,"e":"La hanche est une énarthrose tri-axiale, associant tête fémorale et acétabulum.","s":1},{"q":"Le ligament ilio-fémoral, ou de Bertin :","o":["Est le renfort antérieur, en deux faisceaux","Est le renfort postérieur, en un faisceau","Est intra-articulaire, en un seul faisceau","Est le renfort inférieur, tendu jusqu'au pubis"],"r":0,"e":"Le pubo-fémoral est antérieur et l'ischio-fémoral postérieur.","s":1},{"q":"Pour l'antéro-postérieur de hanche en décubitus dorsal, la main céphalique :","o":["Se place sous la hanche, en arrière, comme main sensitive","Exécute le mouvement par sa base, sous l'EIAS","Se place sur le grand trochanter, puis pousse vers la table","Stabilise le genou contre la table, sans bouger"],"r":0,"e":"La main caudale, en région antérieure sous l'EIAS et au-dessus du grand trochanter, exécute le mouvement par sa base.","s":1},{"q":"Pour le longitudinal caudal de hanche, le kiné :","o":["Se tourne vers la tête et tracte la cuisse vers les pieds","Se tourne vers les pieds et repousse la cuisse vers la tête","Pousse le genou vers la tête, mains sur la rotule","Utilise un drap passé sous la cuisse, debout à côté"],"r":0,"e":"Les deux mains s'emboîtent sur les condyles fémoraux, à la partie distale de la cuisse. Il évite d'agir sur les tissus mous.","s":1},{"q":"Pour le transverse externe de hanche en décubitus dorsal, la précaution porte sur :","o":["Le bord cubital, placé tout près de l'aine","Le genou, qui doit rester en extension","La cheville, tenue en flexion dorsale","Le bassin, maintenu par une sangle"],"r":0,"e":"Hanche et genou sont fléchis, talon sur la table, la cuisse stabilisée contre le tronc du kiné.","s":1},{"q":"Pour le transverse interne de hanche en décubitus dorsal, les coudes sont :","o":["En abduction","En adduction","Fléchis à 90°","En extension complète"],"r":0,"e":"Une main est sur le grand trochanter du côté à mobiliser, l'autre sur le grand trochanter controlatéral, qui sert d'appui.","s":1},{"q":"Pour le transverse externe de hanche en décubitus latéral avec drap :","o":["Côté à traiter en haut, genou calé par la jambe du kiné","Côté à traiter en bas, drap placé autour du bassin","Côté à traiter en haut, drap placé autour du genou","Côté à traiter en bas, kiné poussant vers la table"],"r":0,"e":"Si le drap est trop large pour la zone inguinale, on mobilise alors la diaphyse fémorale. Le kiné tire ensuite vers le plafond.","s":1},{"q":"Pour le postéro-antérieur de hanche en décubitus latéral :","o":["Le kiné est derrière et stabilise l'iliaque en avant","Le kiné est devant et stabilise l'iliaque en arrière","Le kiné est derrière et stabilise le sacrum en arrière","Le kiné est devant, sans stabiliser l'iliaque"],"r":0,"e":"L'antéro-postérieur, qui facilite la rotation externe, stabilise au contraire l'iliaque postérieurement.","s":1},{"q":"Pour l'antéro-postérieur du genou en extension, la main sensitive se place :","o":["Sous le genou, en région poplitée","Sur la TTA, en avant du tibia","Au-dessus de la rotule, en avant","Sur la cheville, en arrière"],"r":0,"e":"Le thénar et l'hypothénar de la main caudale se placent sur la TTA pour exécuter le mouvement.","s":1},{"q":"Pour l'antéro-postérieur du genou fléchi à 70°, le kiné :","o":["S'assoit sur le pied pour le fixer","Tient le pied à la main","Laisse le pied libre","Place un coussin sous le pied"],"r":0,"e":"La main externe stabilise au-dessus de la rotule et la base de la main caudale agit sur la TTA.","s":1},{"q":"La technique dite des « tiroirs » au genou se réalise :","o":["Genoux fléchis, pouces sur la TTA, pied fixé ou non","Genoux tendus, pouces sur la TTA, pied toujours fixé","En décubitus ventral, mains sous le tibia, pied libre","Avec un rouleau sous le genou, pouces sur la rotule"],"r":0,"e":"La variante avec rouleau se fait en légère flexion, pouces sur la TTA et avant-bras du kiné stabilisant le tibia.","s":1},{"q":"Pour le transverse externe du genou fléchi à 90°, la main active est :","o":["Côté interne, bord radial sur la tubérosité du tibia","Côté externe, avec le bord cubital sur la tête du péroné","Sur le fémur, au-dessus de la rotule","Sur la rotule, bord radial en dehors"],"r":0,"e":"L'autre main stabilise le fémur au-dessus de la rotule, épaule en abduction.","s":1},{"q":"Pour le postéro-antérieur du genou en décubitus ventral, la main céphalique :","o":["Pose son bord cubital sur l'arrière du haut du tibia","Se place sur le fémur, au-dessus du creux poplité","Tient la cheville, en soutenant la jambe fléchie","Stabilise le bassin, contre la table d'examen du patient"],"r":0,"e":"À mesure que la flexion augmente, le kiné soutient la jambe sur son avant-bras ; la technique vise à augmenter la flexion.","s":1},{"q":"Pour les longitudinaux du genou en décubitus ventral à 90°, le kiné :","o":["Cale le fémur avec sa jambe et saisit la cheville","Passe un drap sous la cuisse et tracte la jambe","Fixe le bassin d'une main et tient le pied","Stabilise la cuisse avec la main céphalique"],"r":0,"e":"Selon le sens, il réalise une traction ou une compression. Sa jambe est posée sur la face postérieure de la cuisse ; la prise est infra-malléolaire.","s":1},{"q":"L'articulation tibio-péronière supérieure est :","o":["Une arthrodie","Une syndesmose","Une énarthrose","Une trochléenne"],"r":0,"e":"La tibio-péronière inférieure est, elle, une syndesmose fibreuse sans capsule ni liquide.","s":1},{"q":"Pour la compression de la tibio-péronière supérieure, les mains se placent :","o":["Base des mains sur la tête du péroné et sur le tibia","Les deux mains sur la tête du péroné, coudes au corps","Les deux mains sur le tibia, de part et d'autre","Les deux mains sur la rotule, pouces en dedans du genou"],"r":0,"e":"Le mouvement pousse le péroné contre le tibia. La main externe est sur le péroné, l'interne sur le haut du tibia, coudes en abduction.","s":1},{"q":"Quelle est la contre-indication absolue de la mobilisation accessoire ?","o":["L'hypermobilité","L'hypomobilité","La douleur","La raideur capsulaire"],"r":0,"e":"On augmenterait l'instabilité, même en présence de douleur associée.","s":2},{"q":"Sur quel type de mobilité intervient-on ?","o":["L'hypomobilité uniquement","L'hypermobilité uniquement","Les deux indifféremment","Ni l'une ni l'autre"],"r":0,"e":"C'est la règle qui découle directement de la contre-indication.","s":2},{"q":"Que caractérise le grade 1 de Maitland ?","o":["Petite amplitude, au début de la mobilité","Grande amplitude, jusqu'au début de la résistance","Grande amplitude, dans la résistance","Petite amplitude, à la limite de la résistance"],"r":0,"e":"Les grades 1 et 2 traitent la douleur.","s":2},{"q":"Que caractérise le grade 2 de Maitland ?","o":["Grande amplitude jusqu'à la résistance","Petite amplitude au début de la mobilité","Grande amplitude dans la résistance","Manipulation rapide"],"r":0,"e":"2− marque le début de l'amplitude, 2+ la fin.","s":2},{"q":"Que caractérise le grade 3 de Maitland ?","o":["Grande amplitude, dans la résistance","Grande amplitude, jusqu'à la résistance","Petite amplitude, au début de la mobilité","Petite amplitude, rapide, en fin de mobilité"],"r":0,"e":"Les grades 3 et 4 traitent la raideur et les adhérences.","s":2},{"q":"Que caractérise le grade 4 de Maitland ?","o":["Petite amplitude à la limite de la résistance","Grande amplitude dans la résistance","Petite amplitude au début de la mobilité","Manipulation rapide"],"r":0,"e":"Grade 4 : petite amplitude en fin de course résistante.","s":2},{"q":"Que caractérise le grade 5 de Maitland ?","o":["Petite amplitude, rapide, soit la manipulation","Grande amplitude, lente, jusqu'à la résistance","Petite amplitude, lente, au début de la mobilité","Grande amplitude, lente, dans la résistance"],"r":0,"e":"Le grade 5 correspond à la manipulation.","s":2},{"q":"Quels grades utilise-t-on pour la douleur ?","o":["Les grades 1 et 2","Les grades 3 et 4","Le grade 5 uniquement","Tous indifféremment"],"r":0,"e":"Les grades 3 et 4 s'adressent aux adhérences et à la raideur.","s":2},{"q":"Qu'évalue-t-on avec la mobilisation accessoire ?","o":["Mobilité, douleur, désalignements et spasmes","Force musculaire, cotée de 0 à 5","Endurance, sur des séries répétées","Proprioception, en comparant yeux fermés et ouverts"],"r":0,"e":"Quatre paramètres, dans le cadre d'une évaluation subjective et objective.","s":2},{"q":"Comment doit-on entrer et sortir d'une technique ?","o":["De façon progressive dans les deux sens","Rapidement à l'entrée, lentement à la sortie","Lentement à l'entrée, rapidement à la sortie","Indifféremment, selon le confort du kiné et du patient"],"r":0,"e":"Entrée progressive et sortie progressive.","s":2},{"q":"Quelle technique choisir si la flexion d'épaule est limitée ?","o":["Les antéro-postérieurs de l'humérus","Les postéro-antérieurs de l'humérus","Le longitudinal caudal de l'humérus","Le transverse interne de l'humérus"],"r":0,"e":"Flexion → AP ; extension → PA ; abduction → longitudinal caudal.","s":2},{"q":"Quelle technique choisir si l'extension d'épaule est limitée ?","o":["Les postéro-antérieurs de l'humérus","Les antéro-postérieurs de l'humérus","Le longitudinal céphalique de l'humérus","La compression de l'humérus"],"r":0,"e":"L'extension appelle un travail postéro-antérieur.","s":2},{"q":"Quelle technique choisir si l'abduction d'épaule est limitée ?","o":["Le longitudinal caudal","Le longitudinal céphalique","Le transverse interne","Les antéro-postérieurs"],"r":0,"e":"L'abduction s'accompagne d'un glissement inférieur de la tête humérale.","s":2},{"q":"Quelles techniques choisir si la rotation externe est limitée ?","o":["Les postéro-antérieurs et le transverse externe","Les antéro-postérieurs, sans autre technique","Le longitudinal caudal seul, sans autre technique","La compression, associée au transverse interne"],"r":0,"e":"Le transverse externe allonge la capsule antérieure.","s":2},{"q":"Quel glissement accompagne l'abduction de l'épaule ?","o":["Un glissement inférieur","Un glissement supérieur","Un glissement antérieur","Un glissement postérieur"],"r":0,"e":"Abduction → inférieur ; RE → antérieur ; flexion → postérieur.","s":2},{"q":"Quel glissement accompagne la rotation externe de l'épaule ?","o":["Un glissement antérieur","Un glissement postérieur","Un glissement inférieur","Un glissement supérieur"],"r":0,"e":"Il faut connaître les trois par cœur.","s":2},{"q":"Quel glissement accompagne la flexion de l'épaule ?","o":["Un glissement postérieur","Un glissement antérieur","Un glissement inférieur","Un glissement supérieur"],"r":0,"e":"La flexion s'accompagne d'un glissement postérieur de la tête humérale.","s":2},{"q":"Quelle est l'indication du transverse externe / traction à l'épaule ?","o":["Gagner en extensibilité des tissus non contractiles","L'hypotonie musculaire autour de l'épaule","L'instabilité chronique, avec appréhension en rotation externe","La douleur aiguë, juste après un traumatisme"],"r":0,"e":"Le transverse interne, lui, s'adresse à l'hypotonie et au manque de stabilité. Indications : capsulite adhésive, hypomobilité et adhérences.","s":2},{"q":"Quelle est l'indication du transverse interne / compression à l'épaule ?","o":["L'hypotonie ou le manque de stabilité articulaire","La capsulite adhésive, en phase d'enraidissement","Les adhérences, après une longue immobilisation du bras","La raideur post-immobilisation, en rotation"],"r":0,"e":"La compression est réalisée de façon bilatérale.","s":2},{"q":"Comment exécuter le transverse externe / traction ?","o":["Abduction, main à l'aisselle, retour, puis traction","Traction directe, sans aucune préparation du bras","Compression d'abord, puis traction progressive","Rotation externe d'abord, puis traction lente"],"r":0,"e":"Le cours insiste : ATTENTION lors du placement près de l'aisselle. On revient en position initiale avant de tracter.","s":2},{"q":"Quel est l'intérêt du longitudinal caudal à l'épaule ?","o":["Stabilité dynamique, proprioception, coaptation","Rupture des adhérences et gain d'extensibilité capsulaire","Antalgie pure, sans effet mécanique","Gain d'extension et de rotation interne"],"r":0,"e":"Il faut stabiliser la clavicule pendant l'exécution.","s":2},{"q":"Quelle structure faut-il stabiliser pendant le longitudinal caudal ?","o":["La clavicule et l'acromio-claviculaire","La scapula seule, par son bord interne","Le coude, maintenu fléchi contre le tronc","Le poignet, maintenu en position neutre"],"r":0,"e":"Le cours le signale explicitement.","s":2},{"q":"Quelle position adopte le kiné pour le postéro-antérieur gléno-huméral ?","o":["Derrière la tête, à genoux, table plus haute","Face au patient, debout, table basse","Latéralement, assis, table à hauteur de hanche","Au pied de la table, debout, table basse"],"r":0,"e":"En antéro-postérieur, il est face au patient.","s":2},{"q":"Que réalise la clavicule pendant l'abduction de l'épaule ?","o":["Élévation, rotation postérieure et rétraction","Abaissement, rotation antérieure et protraction","Élévation, rotation antérieure et protraction","Abaissement, rotation postérieure et rétraction"],"r":0,"e":"Trois composantes à retenir.","s":2},{"q":"Quelle particularité le postéro-antérieur sterno-claviculaire présente-t-il ?","o":["Il se fait sans grades ni résistance","Il exige toujours un grade 4","Il se fait en décubitus ventral","Il utilise le bord cubital"],"r":0,"e":"On agrippe avec les 2e-5e doigts sous le 1/3 moyen de la clavicule.","s":2},{"q":"Quelle est la position du patient pour les mouvements accessoires scapulo-thoraciques ?","o":["Décubitus latéral, membre supérieur soutenu","Décubitus dorsal, bras le long du corps","Décubitus ventral, bras hors de la table","Assis, bras croisés sur la poitrine"],"r":0,"e":"Le bras céphalique du kiné passe sous le bras du patient.","s":2},{"q":"Quelle est la règle d'ordre au poignet ?","o":["1° traction, puis 2° accessoires","1° accessoires, puis 2° traction","Traction et accessoires simultanés","Aucun ordre imposé"],"r":0,"e":"Le cours rappelle aussi que mouvement accessoire ≠ mouvement physiologique.","s":2},{"q":"Pourquoi place-t-on le coude à 45° de flexion pour l'huméro-cubitale ?","o":["Pour éviter le verrouillage articulaire","Pour détendre le biceps, bi-articulaire","Pour faciliter la prise du kiné","Pour protéger le poignet du patient"],"r":0,"e":"Le coude est aussi placé en supination.","s":2},{"q":"Quel os mobilise-t-on aux articulations radio-cubitales ?","o":["Le radius, car c'est lui qui est mobile","Le cubitus, car il tourne autour du radius","Les deux, mobilisés en même temps","L'humérus, car il entraîne les deux os de l'avant-bras"],"r":0,"e":"Le cours insiste : on mobilise le radius, et la main ne le quitte pas.","s":2},{"q":"Combien de points comporte l'évaluation du carpe selon Kaltenborn ?","o":["Dix","Huit","Douze","Six"],"r":0,"e":"Les 10 points de Kaltenborn, en position assise et pronation.","s":2},{"q":"Les grades de mouvement cités dans cette fiche proviennent de :","o":["Kisner et Colby, 2018","Kaltenborn, 2018","Cyriax et Janda, 2018","Mulligan, 2018"],"r":0,"e":"Les grades 1 et 2 visent la douleur, les 3 et 4 la raideur et les adhérences, le 5 étant la manipulation.","s":2},{"q":"L'hypermobilité contre-indique la mobilisation accessoire parce qu'on :","o":["Augmenterait l'instabilité, même si une douleur existe","Provoquerait une fracture, par fatigue de l'os","Déclencherait une inflammation de la capsule","Rendrait impossible la lecture de l'end-feel du patient"],"r":0,"e":"On n'intervient que sur l'hypomobilité.","s":2},{"q":"L'évaluation de l'épaule suit l'ordre :","o":["Posture, mouvements actifs et passifs, puis accessoires","Mouvements accessoires, puis passifs, puis posture","Mouvements passifs, puis actifs, puis posture","Posture, puis accessoires, puis actifs et passifs"],"r":0,"e":"La démarche générale reste évaluation, enregistrement, raisonnement clinique, intervention.","s":2},{"q":"L'articulation sterno-claviculaire est de type :","o":["Plane","En selle","Énarthrose","Fausse articulation"],"r":1,"e":"L'acromio-claviculaire est plane, la gléno-humérale une énarthrose et la scapulo-thoracique une fausse articulation.","s":2},{"q":"Lors de l'abduction, la clavicule réalise :","o":["Élévation, rotation postérieure et rétraction","Abaissement, rotation postérieure et protraction","Élévation, rotation antérieure et protraction marquée","Abaissement, rotation antérieure et rétraction"],"r":0,"e":"Cette cinématique claviculaire accompagne le rythme scapulo-huméral.","s":2},{"q":"Pour le postéro-antérieur gléno-huméral, le kiné se place :","o":["Derrière la tête, à genoux, table plus haute","Face au patient, debout, table basse","De profil, assis, table à la hauteur de sa hanche","Aux pieds du patient, debout, table basse"],"r":0,"e":"Le contact se fait sur la tête humérale, poussée vers le plafond ; l'indication est une diminution d'extension ou de rotation externe.","s":2},{"q":"Pour le longitudinal céphalique gléno-huméral :","o":["Une main au milieu du bras, l'autre sur l'acromio-claviculaire","Une main au coude, l'autre sur la scapula, poussée vers les pieds","Une main sur la scapula, l'autre au poignet, traction","Une main au bas du bras, l'autre libre, poussée vers la tête"],"r":0,"e":"Le longitudinal caudal, lui, exerce une traction vers les membres inférieurs. Le mouvement va vers la tête.","s":2},{"q":"Les effets attribués au longitudinal caudal de l'épaule sont :","o":["Stabilité dynamique, proprioception et coaptation","Extensibilité et rupture des adhérences","Compression bilatérale et coaptation","Gain de rotation interne, et d'extension horizontale"],"r":0,"e":"Son indication est une diminution d'abduction.","s":2},{"q":"L'indication du transverse interne, ou compression, de l'épaule est :","o":["Une hypotonie ou un manque de stabilité","Une capsulite adhésive, enraidie","Une hypomobilité, après immobilisation","Une rupture des cross-links du collagène capsulaire"],"r":0,"e":"La main soutient la portion distale du bras, l'autre agissant sur la tête humérale vers l'intérieur. Le manque de stabilité est articulaire.","s":2},{"q":"L'indication du transverse externe, ou traction, de l'épaule est :","o":["Gagner en extensibilité des tissus non contractiles","L'hypotonie musculaire, avec un manque de stabilité articulaire","L'instabilité, avec appréhension en rotation externe","La douleur aiguë, juste après un traumatisme"],"r":0,"e":"Sa procédure impose de faire d'abord une abduction, de placer la main près de l'aisselle, de revenir en position initiale, puis de tracter. Il s'agit de la capsulite adhésive, de l'hypomobilité et de la rupture des adhérences et cross-links.","s":2},{"q":"Les prérequis de la mobilisation d'épaule en décubitus dorsal sont :","o":["Scapula et tronc stables, sécurité, travail avec le corps","La seule stabilité du tronc, sans autre exigence","L'absence totale de douleur avant la séance","Une table basse, avec le patient en bord de table et sanglé"],"r":0,"e":"En décubitus latéral, la scapula est plus instable. On utilise son corps plutôt que ses bras.","s":2},{"q":"Une diminution de rotation externe d'épaule oriente vers :","o":["Des postéro-antérieurs associés à un transverse externe","Un longitudinal caudal, associé à une compression","Des antéro-postérieurs, associés à un transverse interne","Une compression, associée à un longitudinal céphalique"],"r":0,"e":"Une flexion diminuée oriente vers les antéro-postérieurs et une abduction diminuée vers le longitudinal caudal. Cela allonge la capsule antérieure.","s":2},{"q":"Pour le postéro-antérieur sterno-claviculaire, la particularité est :","o":["Qu'il se fait sans grades ni résistance, peau poussée","Qu'il exige le grade 4, en fin d'amplitude","Qu'il se fait en décubitus latéral, bras soutenu","Qu'il utilise les deux pouces, posés sur le sternum du patient"],"r":0,"e":"Les doigts du 2ᵉ au 5ᵉ se placent sous le tiers moyen de la clavicule pour tirer vers le plafond. On pousse la peau pour créer l'espace.","s":2},{"q":"L'antéro-postérieur acromio-claviculaire se fait par contact sur :","o":["La face antérieure du tiers externe de la clavicule","La face antérieure du tiers interne de la clavicule","La face antérieure du sternum, près de l'interligne","La face postérieure de l'épine de la scapula"],"r":0,"e":"Pour la sterno-claviculaire, le contact porte sur la face antérieure du tiers interne, le sternum ou l'interligne. On peut aussi contacter l'acromion ou l'interligne.","s":2},{"q":"Pour le longitudinal caudal acromio-claviculaire, le kiné :","o":["Est derrière la tête et pousse la clavicule vers les pieds","Se place face au patient et tire la clavicule vers lui","Agit sur le sternum et pousse la clavicule vers le plafond","Pousse la face inférieure de la clavicule vers la tête"],"r":0,"e":"Le longitudinal céphalique sterno-claviculaire se fait, lui, kiné tourné vers la tête, sur la face inférieure de la clavicule. Il agit sur la face supérieure de la clavicule.","s":2},{"q":"Les mouvements accessoires scapulo-thoraciques se réalisent :","o":["En décubitus latéral, membre supérieur soutenu","En décubitus dorsal, bras le long du corps","En décubitus ventral, bras pendant hors de la table","En position assise, bras croisés sur le thorax"],"r":0,"e":"Le bras céphalique du kiné passe sous le bras du patient pour contacter le bord supérieur ou la face interne de l'omoplate.","s":2},{"q":"Pour l'abduction et l'adduction scapulo-thoraciques, les mains se placent sur :","o":["Le bord interne et le bord externe de l'omoplate","L'angle inférieur et le bord supérieur","L'acromion et la pointe de la coracoïde, en avant","L'épine de la scapula et l'angle supérieur"],"r":0,"e":"L'angle inférieur et le bord supérieur servent, eux, à l'élévation-abaissement et aux rotations.","s":2},{"q":"Le principe d'entrée et de sortie d'une technique de mobilisation accessoire est :","o":["Progressif dans les deux sens","Brutal à l'entrée","Progressif à l'entrée seulement","Sans importance"],"r":0,"e":"Les objectifs restent la diminution de la douleur et l'augmentation d'amplitude.","s":2},{"q":"Au poignet, la règle d'ordre impose :","o":["D'abord la traction, puis les accessoires","D'abord les accessoires, puis la traction","La traction seule, sans aucun accessoire","Les accessoires seuls, sans traction"],"r":0,"e":"Le cours rappelle par ailleurs que mouvement accessoire et mouvement physiologique sont deux choses distinctes.","s":2},{"q":"La règle des glissements à l'épaule associe la flexion à un glissement :","o":["Inférieur","Antérieur","Postérieur","Latéral"],"r":2,"e":"L'abduction s'accompagne d'un glissement inférieur et la rotation externe d'un glissement antérieur.","s":2},{"q":"Comment définit-on un valgus ?","o":["Le segment distal s'éloigne de la ligne médiane du corps","Le segment distal se rapproche de la ligne médiane","Le segment proximal se déplace en dedans","Il y a une rotation interne"],"r":0,"e":"Le varus, à l'inverse, rapproche le segment distal de la ligne médiane.","s":3},{"q":"Comment définit-on un varus ?","o":["Le segment distal se rapproche de la ligne médiane","Le segment distal s'éloigne de la ligne médiane du corps","Le segment proximal s'écarte de la ligne médiane","Le segment distal tourne en rotation externe"],"r":0,"e":"Valgus = éloignement, varus = rapprochement.","s":3},{"q":"Pourquoi ne faut-il pas confondre valgus et rotation interne ?","o":["Ce sont deux altérations distinctes, à ne pas mélanger","Ce sont deux synonymes, utilisés l'un pour l'autre","La rotation interne est pathologique, le valgus non","Le valgus n'existe pas au genou, seulement au pied"],"r":0,"e":"Le cours avertit explicitement : valgus ≠ rotation interne. Il faut aussi vérifier la torsion tibiale.","s":3},{"q":"Quelle est la norme de l'angle Q ?","o":["Inférieur à 15°","Inférieur à 5°","Entre 20 et 25°","Supérieur à 20°"],"r":0,"e":"10-14° chez l'homme, 15-17° chez la femme.","s":3},{"q":"Quelle est la valeur de l'angle Q chez l'homme ?","o":["10 à 14°","15 à 17°","20 à 25°","5 à 8°"],"r":0,"e":"La valeur féminine est plus élevée, du fait d'un bassin plus large.","s":3},{"q":"Quelle est la valeur de l'angle Q chez la femme ?","o":["15 à 17°","10 à 14°","20 à 25°","8 à 10°"],"r":0,"e":"L'écart s'explique par la largeur du bassin.","s":3},{"q":"Quels sont les trois repères de mesure de l'angle Q ?","o":["EIAS, centre de la rotule et tubérosité tibiale","EIAS, grand trochanter et malléole externe du pied","Crête iliaque, centre de la rotule et malléole","EIPS, bord supérieur de la rotule et tubérosité"],"r":0,"e":"EIAS pour le bras proximal, rotule pour l'axe, TTA pour le bras distal.","s":3},{"q":"Quelle valeur d'angle cranio-vertébral signe une antériorisation de la tête ?","o":["Inférieure à 50°","Supérieure à 55°","Entre 50 et 55°","Supérieure à 60°"],"r":0,"e":"50-55° est la zone normale.","s":3},{"q":"Comment se mesure l'angle cranio-vertébral ?","o":["Entre la ligne C7-tragus et l'horizontale de C7","Entre la ligne acromion-oreille et la verticale","Entre la ligne menton-sternum et l'horizontale","Entre la ligne occiput-T1 et la verticale du corps"],"r":0,"e":"Les repères de mesure sont le tragus, l'acromion et le bord supérieur du manubrium.","s":3},{"q":"Quel signe clinique simple traduit l'antériorisation de la tête ?","o":["Le lobe de l'oreille est en avant de l'acromion","Le menton est relevé au-dessus de l'horizontale","Les épaules sont en arrière de la ligne de gravité","Le regard est baissé vers le sol"],"r":0,"e":"C'est le repère d'observation le plus rapide en vue de profil.","s":3},{"q":"Quel signe traduit une rétraction musculaire du pectoral ?","o":["La rotation interne des épaules","L'antériorisation de la tête","L'abduction des omoplates seule","La bascule antérieure du bassin"],"r":0,"e":"Le cours associe explicitement rotation interne des épaules et rétraction du pectoral.","s":3},{"q":"Par où passe la ligne de gravité au niveau du crâne ?","o":["Légèrement en arrière du sommet de la suture coronale","Légèrement en avant du sommet de la suture coronale","Exactement au bregma, au sommet du crâne","Par le lambda, à l'arrière du crâne"],"r":0,"e":"Mémo : arrière au crâne et à la hanche, avant au genou et à la cheville.","s":3},{"q":"Par où passe la ligne de gravité au niveau de la hanche ?","o":["Légèrement en arrière de l'axe de la coxo-fémorale","Légèrement en avant de l'axe de la coxo-fémorale","Exactement par le sommet du grand trochanter","Par la symphyse pubienne, en avant"],"r":0,"e":"L'axe de référence est le grand trochanter.","s":3},{"q":"Par où passe la ligne de gravité au niveau du genou ?","o":["Légèrement en avant de l'axe du genou","Légèrement en arrière de l'axe du genou","Exactement par le centre du genou","Par la tête du péroné, en dehors du genou"],"r":0,"e":"En avant du genou et en avant de la malléole externe.","s":3},{"q":"Par où passe la ligne de gravité au niveau de la cheville ?","o":["Légèrement en avant de la malléole externe","En arrière de la malléole externe","Par le centre de la malléole interne","Par le centre du calcanéum, au talon"],"r":0,"e":"C'est le dernier des sept points de la ligne de gravité.","s":3},{"q":"Quel conduit la ligne de gravité traverse-t-elle à la tête ?","o":["Le méat auditif externe","Le conduit lacrymal","Le foramen magnum","Le sinus frontal"],"r":0,"e":"C'est le deuxième point de la ligne idéale.","s":3},{"q":"Quelle bascule du bassin caractérise la posture cyphotique-lordotique ?","o":["L'inclinaison antérieure (antéversion)","L'inclinaison postérieure (rétroversion)","La déviation antérieure sans bascule","Aucune bascule"],"r":0,"e":"L'antéversion est le signe distinctif de cette posture.","s":3},{"q":"Quelle bascule du bassin caractérise la posture flat back ?","o":["L'inclinaison postérieure, ou rétroversion","L'inclinaison antérieure, ou antéversion","La déviation antérieure, ou translation","Une obliquité latérale, ou bascule"],"r":0,"e":"Rétroversion + rectification lombaire signent le flat back.","s":3},{"q":"Quelle particularité du bassin caractérise la posture sway-back ?","o":["Une déviation antérieure, avec inclinaison postérieure","Une antéversion pure, sans déviation antérieure","Une rétroversion pure, sans déviation antérieure","Une obliquité latérale, avec bascule du côté dominant"],"r":0,"e":"C'est la déviation antérieure qui distingue le sway-back.","s":3},{"q":"Que devient la cyphose dorsale dans la posture flat back ?","o":["Elle est réduite","Elle est augmentée","Elle est inchangée","Elle s'inverse complètement"],"r":0,"e":"Partie supérieure en flexion augmentée, partie inférieure rectiligne.","s":3},{"q":"Que devient la lordose lombaire dans la posture flat back ?","o":["Elle est rectifiée","Elle est augmentée","Elle est inchangée","Elle s'inverse"],"r":0,"e":"Flexion du rachis lombaire et rectification de la lordose.","s":3},{"q":"Que devient la lordose lombaire dans la posture cyphotique-lordotique ?","o":["Elle est augmentée","Elle est rectifiée","Elle est inchangée","Elle s'inverse"],"r":0,"e":"Hyperextension lombaire et antéversion du bassin.","s":3},{"q":"Quel signe scapulaire caractérise la posture cyphotique-lordotique ?","o":["L'abduction des omoplates","L'adduction des omoplates","La sonnette interne","Le décollement du bord spinal"],"r":0,"e":"C'est le seul signe scapulaire cité dans les trois postures.","s":3},{"q":"Que devient le rachis dorsal dans la posture sway-back ?","o":["Sa flexion est augmentée","Il est en extension","Il est rectifié","Il est inchangé"],"r":0,"e":"Flexion augmentée du dorsal et légère extension lombaire.","s":3},{"q":"Quel signe est commun aux trois postures pathologiques ?","o":["L'antériorisation de la tête","La rétroversion du bassin","L'hyperextension des genoux","L'abduction des omoplates"],"r":0,"e":"Les trois postures commencent par l'antériorisation de la tête.","s":3},{"q":"Combien de points la check-list du plan postérieur comporte-t-elle ?","o":["Seize","Dix","Douze","Vingt"],"r":0,"e":"De l'inclinaison de la tête au transfert de poids.","s":3},{"q":"Que faut-il observer sur les scapulas en vue postérieure ?","o":["Angle inférieur, bord médial, épine et écart aux épineuses","L'angle inférieur seul, comparé au côté opposé","L'épine seule, en comparant sa hauteur à celle de l'autre côté","La fosse subscapulaire, palpée en avant"],"r":0,"e":"Quatre éléments, dont la distance aux épineuses.","s":3},{"q":"Quelles sont les deux questions préalables à toute évaluation posturale ?","o":["Posture relâchée ou anatomique ? Quelle consigne ?","Debout ou assis ? Chaussé ou pieds nus ?","Avant ou après l'effort ? Face au miroir ou non ?","Habillé ou déshabillé ? Seul ou accompagné ?"],"r":0,"e":"La consigne donnée conditionne la posture observée.","s":3},{"q":"Quel ordre d'observation le cours recommande-t-il ?","o":["Céphalo-caudal ou caudo-céphalique","Uniquement de haut en bas","Uniquement de bas en haut","Du centre vers la périphérie"],"r":0,"e":"Les deux sens sont acceptés, à condition d'être systématique.","s":3},{"q":"Quelle confusion faut-il éviter en vue antérieure au niveau des épaules ?","o":["Confondre la ligne des acromions et celle du trapèze","Confondre l'acromion et l'extrémité de la clavicule","Confondre l'épaule droite et l'épaule gauche du patient","Confondre l'acromion et la pointe de la coracoïde"],"r":0,"e":"Le cours signale explicitement : ligne acromion ≠ ligne du trapèze supérieur.","s":3},{"q":"Les deux questions préalables à tout bilan postural sont :","o":["Relâchée ou anatomique, et quelle consigne donner","Debout ou assis, et depuis combien de temps","Avec ou sans chaussures, et à quelle heure de la journée","Homme ou femme, et quel est l'âge du patient"],"r":0,"e":"La consigne conditionne directement la posture observée.","s":3},{"q":"L'ordre d'évaluation des segments est :","o":["Tête, colonne, ceintures et membres, de haut en bas","Membres inférieurs, puis la tête, sans les ceintures","Dans un ordre aléatoire, selon la plainte du patient","Colonne, puis tête, puis membres, du centre vers la périphérie"],"r":0,"e":"Cet ordre peut être céphalo-caudal ou caudo-céphalique. Ordre détaillé : tête, colonne, ceinture scapulaire, membres supérieurs, ceinture pelvienne, membres inférieurs.","s":3},{"q":"En vue antérieure, le niveau des épaules s'apprécie :","o":["Sur l'acromion et la ligne du trapèze, sans confusion","Sur le seul acromion, à droite et à gauche","Sur la seule ligne du trapèze supérieur","Sur les clavicules, comparées à l'horizontale des épaules"],"r":0,"e":"C'est une confusion classique du bilan en vue antérieure.","s":3},{"q":"L'inclinaison de la tête s'apprécie sur :","o":["Le lobe de l'oreille et le menton","L'acromion et la clavicule","Le tragus seul, de profil","Les clavicules et la ligne des yeux"],"r":0,"e":"Ces repères valent en vue antérieure comme en vue postérieure.","s":3},{"q":"En vue antérieure, la rotule s'apprécie par :","o":["Son bord supérieur et la tubérosité tibiale","Son bord inférieur et la tête du péroné","Son axe vertical, comparé à celui de la diaphyse fémorale","Sa taille, comparée à celle de l'autre côté"],"r":0,"e":"Genoux et cheville s'examinent ensuite en valgus ou varus.","s":3},{"q":"Le valgus se définit comme :","o":["Un segment distal qui s'éloigne de la ligne médiane","Un segment distal qui s'en rapproche","Une rotation interne du segment distal","Une torsion du tibia, autour de son axe longitudinal"],"r":0,"e":"Le varus correspond au rapprochement ; il ne faut pas confondre valgus et rotation interne, et il faut vérifier la torsion tibiale.","s":3},{"q":"Pour la mesure de l'angle Q au goniomètre, le bras proximal vise :","o":["L'EIAS, du côté mesuré","La TTA, sous la rotule mesurée","Le grand trochanter","La malléole externe"],"r":0,"e":"L'axe se place au centre de la rotule et le bras distal sur la tubérosité tibiale antérieure.","s":3},{"q":"La valeur normale de l'angle Q chez l'homme est de :","o":["10 à 14°","15 à 17°","18 à 20°","5 à 9°"],"r":0,"e":"Chez la femme, elle est de 15 à 17°, la norme générale restant inférieure à 15°.","s":3},{"q":"Parmi les 16 points de la check-list du plan postérieur figure :","o":["La position des scapulas, dont l'écart aux épineuses","La position de la rotule, vue de dos en flexion du genou","La présence d'un pectus excavatum, vue de dos","La mesure de l'angle Q, depuis la face postérieure"],"r":0,"e":"S'y ajoutent les gibbosités, l'alignement des épineuses, les EIPS et les tendons d'Achille. On observe l'angle inférieur, le bord médial et l'épine.","s":3},{"q":"Les repères principaux du plan postérieur sont :","o":["Acromion, épine et angle de l'omoplate, EIPS, gibbosité","Rotule, tubérosité tibiale, EIAS, malléole interne et hallux","Tragus, acromion, manubrium et lobe de l'oreille","Clavicules, sternum, ligne blanche et ombilic"],"r":0,"e":"L'EIPS renseigne notamment sur l'obliquité pelvienne.","s":3},{"q":"Dans l'alignement idéal, la ligne de gravité passe au crâne :","o":["Légèrement en arrière du sommet de la suture coronale","Légèrement en avant du sommet de la suture coronale","Exactement au sommet de la suture coronale, au bregma","Au vertex, sur la ligne médiane du crâne"],"r":0,"e":"Le mémo est : arrière au crâne et à la hanche, avant au genou et à la cheville.","s":3},{"q":"La ligne de gravité passe, au niveau de la hanche :","o":["Légèrement en arrière de l'axe du grand trochanter","Légèrement en avant de l'axe du grand trochanter","Exactement sur l'axe de la coxo-fémorale","En dehors du grand trochanter, sur sa face latérale"],"r":0,"e":"Elle passe légèrement en avant de l'axe du genou et de la malléole externe.","s":3},{"q":"La ligne de gravité traverse :","o":["Le méat auditif externe","Le conduit lacrymal","Le tragus","L'orbite"],"r":0,"e":"Elle passe aussi par les corps vertébraux de la majorité des vertèbres cervicales et lombaires et par l'articulation de l'épaule.","s":3},{"q":"L'angle cranio-vertébral se mesure :","o":["Entre la ligne C7-tragus et l'horizontale de C7","Entre la ligne acromion-tragus et la verticale","Entre la ligne C7-acromion et l'horizontale","Entre la ligne menton-sternum et la verticale du corps"],"r":0,"e":"Ses repères sont le tragus, l'acromion et le bord supérieur du manubrium ; une valeur inférieure à 50° signe une antériorisation.","s":3},{"q":"La rotation interne des épaules traduit :","o":["Une rétraction musculaire du pectoral","Une antériorisation isolée de la tête","Une hypercyphose dorsale, à grand rayon","Une bascule pelvienne en avant"],"r":0,"e":"Le lobe de l'oreille en avant de l'acromion signe, lui, l'antériorisation de la tête.","s":3},{"q":"La check-list du plan latéral comprend notamment :","o":["Courbures, symétrie, épaules, thorax en tonneau, pieds","Gibbosités, épineuses et position des omoplates","EIPS, tendons d'Achille et plis fessiers","Clavicules, sternum, rotules et angle Q en vue de face"],"r":0,"e":"Elle se réfère aux travaux de Kendall (2005). On observe la rétraction ou la protraction des épaules et l'alignement des pieds.","s":3},{"q":"Le signe commun aux trois postures pathologiques est :","o":["L'antériorisation de la tête","L'hyperlordose lombaire","La bascule antérieure du bassin","La diminution de la cyphose"],"r":0,"e":"Cyphotique-lordotique, flat back et sway-back la partagent toutes trois.","s":3},{"q":"Dans la posture flat back, le rachis dorsal :","o":["Est en extension, avec une diminution de la cyphose","Est en flexion, avec une augmentation de la cyphose","Est inchangé, avec une cyphose normale","Est en rotation, avec une gibbosité du côté convexe"],"r":0,"e":"Dans la posture cyphotique-lordotique, il est au contraire en flexion avec augmentation de la cyphose.","s":3},{"q":"En vue antérieure, le thorax s'apprécie par :","o":["La distinction entre pectus carinatum et excavatum","La présence de gibbosités, visibles en flexion","La ligne des épineuses, du sommet à la base","Le relief du tendon d'Achille et le pli fessier, de face"],"r":0,"e":"Le bassin s'apprécie ensuite par son horizontalité, les EIAS et le grand trochanter.","s":3},{"q":"Le rachis cervical, dans les trois postures pathologiques, est :","o":["En hyperextension, sauf dans la flat back, en extension","Toujours en flexion, quelle que soit la posture","Toujours rectiligne, quelle que soit la posture","Sans modification, la tête restant bien dans l'axe du tronc"],"r":0,"e":"L'antériorisation de la tête accompagne ces trois tableaux. L'hyperextension concerne la cyphotique-lordotique et la sway-back.","s":3}]};
